#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  # A terminal in canonical mode silently cuts a pasted line at 4095 chars,
  # which truncates long secrets like signing keys. Read non-canonically.
  local saved_tty=""
  if [[ -t 0 ]]; then saved_tty=$(stty -g); stty -icanon; fi
  read -rs input || rc=1
  [[ -n "$saved_tty" ]] && stty "$saved_tty"
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
#
# Knock Development setup for the "Does Knock hold up against Cadence?" checks
# (wayfinder map #6, tickets #10 and #11). Ephemeral: delete when done.
# Run from anywhere:  bash scripts/knock-dev-setup.wizard.sh

run_wizard() {

TOTAL_STAGES=7
# Always target the repo root's .env, wherever the wizard is run from.
ENV_FILE="${ENV_FILE_OVERRIDE:-$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)/.env}"

banner "Knock: Development setup for Cadence Notifications"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Create your Knock account"
say "Knock is the vendor picked in \"Pick the notification vendor\". Free plan, no card."
open_url "https://dashboard.knock.app/signup"
step "Sign up (or log in if you already have an account)."
step "Find the environment switcher in the dashboard and choose ${BOLD}Development${RESET}."
note "Every step below happens in Development, never Production."
pause "Press Enter when you're in the Development environment"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "API keys"
open_url "https://dashboard.knock.app"
step "Go to ${BOLD}Platform → API keys${RESET} (check that the environment still says Development)."
step "Copy the ${BOLD}public${RESET} key (starts with pk_test_)."
ask KNOCK_PUBLIC_API_KEY "Paste the public key:"
[[ "$KNOCK_PUBLIC_API_KEY" == pk_test_* ]] || warn "doesn't start with pk_test_. Is this the Development key?"
step "Copy the ${BOLD}secret${RESET} key (starts with sk_test_)."
ask_secret KNOCK_SECRET_API_KEY "Paste the secret key (hidden):"
[[ "$KNOCK_SECRET_API_KEY" == sk_test_* ]] || warn "doesn't start with sk_test_. Is this the Development key?"
write_env KNOCK_PUBLIC_API_KEY "$KNOCK_PUBLIC_API_KEY"
write_env KNOCK_SECRET_API_KEY "$KNOCK_SECRET_API_KEY"
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Signing key + enhanced security"
say "Cadence signs a token for whichever user DevUI selects, so feeds aren't open to anyone."
step "Still on ${BOLD}Platform → API keys${RESET}, find ${BOLD}Application Signing Keys${RESET} and generate one."
step "Copy the ${BOLD}base64-encoded${RESET} private key: it's a single line. (The PEM form is under 'Advanced'; skip that.)"
warn "Knock only shows the private key once. If you lose it, generate a new one."
ask_secret KNOCK_SIGNING_KEY "Paste the base64 signing key (hidden):"
if ! printf '%s' "$KNOCK_SIGNING_KEY" | base64 -d 2>/dev/null | grep -q 'END PRIVATE KEY'; then
  warn "That doesn't decode to a complete private key (no END line). Was it cut off or mis-copied?"
fi
write_env KNOCK_SIGNING_KEY "$KNOCK_SIGNING_KEY"
say ""
step "Turn on ${BOLD}enhanced security mode${RESET} for Development."
note "The docs don't say exactly where this toggle is. Look on the API keys page first, then the environment settings."
note "Once it's on, any feed request without a signed user token is refused. That's what we want."
pause "Press Enter once enhanced security is on"

# ── 4 ────────────────────────────────────────────────────────────────────
stage "In-app feed channel"
open_url "https://dashboard.knock.app/~/settings/integrations/channels"
step "In ${BOLD}Channels and sources${RESET}, create a new channel of type ${BOLD}In-app feed${RESET} (provider: Knock)."
step "Name it ${BOLD}Cadence feed${RESET}."
step "Open the channel and copy its ${BOLD}channel ID${RESET} (a UUID)."
ask KNOCK_FEED_CHANNEL_ID "Paste the channel ID:"
[[ "$KNOCK_FEED_CHANNEL_ID" =~ ^[0-9a-fA-F-]{36}$ ]] || warn "that doesn't look like a UUID. Check it's the channel ID, not its name."
write_env KNOCK_FEED_CHANNEL_ID "$KNOCK_FEED_CHANNEL_ID"
pause

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Workflow: discussion-question (checks 2 & 3)"
say "This is the workflow the server-side trigger will fire: Discussion Question → Instructor."
open_url "https://dashboard.knock.app"
step "Go to ${BOLD}Workflows${RESET} and create a new workflow."
step "Name: ${BOLD}Discussion Question${RESET}. Key: ${BOLD}discussion-question${RESET} (exactly; the code uses it)."
step "Add an ${BOLD}In-app feed${RESET} channel step and pick the ${BOLD}Cadence feed${RESET} channel."
step "Click ${BOLD}Edit content${RESET} on the step and set:"
note "    Body:          **{{ actor_name }}** asked a question on “{{ lesson_title }}”"
note "    Click action:  turn on 'include click action', URL = {{ url }}"
step "From the workflow's ${BOLD}…${RESET} menu choose ${BOLD}Manage workflow${RESET} and add the category ${BOLD}discussions${RESET}."
step "Commit the changes to Development (Commits page → ${BOLD}Commit all${RESET} works too)."
note "Button labels in the workflow builder aren't in the docs. If one differs, follow what it's for."
pause "Press Enter once discussion-question is committed"

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Workflow: new-enrollment (check 4)"
say "This is the one meant to be off by default for Instructors."
step "Create another workflow. Name: ${BOLD}New Enrollment${RESET}. Key: ${BOLD}new-enrollment${RESET}."
step "Add an ${BOLD}In-app feed${RESET} step on ${BOLD}Cadence feed${RESET}. Edit content:"
note "    Body:          **{{ actor_name }}** enrolled in {{ course_title }}"
note "    Click action:  on, URL = {{ url }}"
step "${BOLD}Manage workflow${RESET} → add the category ${BOLD}enrollments${RESET}."
step "Commit to Development."
note "Don't set any preferences here. The prototype code turns 'enrollments' off per user through the API, then opts back in."
pause "Press Enter once new-enrollment is committed"

# ── 7 ────────────────────────────────────────────────────────────────────
stage "Smoke test (optional)"
say "Fires discussion-question once at Sarah Chen (user 2, an Instructor) with your secret key."
note "This sends 1 message from the 10k/month free allowance and creates user 2 in Knock."
if ! command -v curl >/dev/null 2>&1; then
  SKIPPED+=("smoke test: curl not installed")
  warn "curl isn't installed, so skipping."
elif confirm "Send the test trigger?"; then
  body='{"recipients":[{"id":"2","name":"Sarah Chen"}],"data":{"actor_name":"James Park","lesson_title":"Primitive Types","url":"/courses/introduction-to-typescript/lessons/4"}}'
  resp=$(curl -sS -w '\n%{http_code}' -X POST "https://api.knock.app/v1/workflows/discussion-question/trigger" \
    -H "Authorization: Bearer $KNOCK_SECRET_API_KEY" -H "Content-Type: application/json" -d "$body" || true)
  code="${resp##*$'\n'}"
  if [[ "$code" == 2* ]]; then
    printf '  %s✓ trigger accepted%s (%s)\n' "$GREEN" "$RESET" "${resp%$'\n'*}"
    step "In the dashboard, open the message logs and check that one In-app message went to user 2."
    pause
  else
    warn "trigger failed (HTTP $code): ${resp%$'\n'*}"
    note "Check the secret key, the workflow key 'discussion-question', and that it's committed to Development."
    SKIPPED+=("smoke test failed (HTTP $code). Fix it and re-run the wizard; saved values are kept")
    pause
  fi
else
  SKIPPED+=("smoke test not run")
fi

finish
note "Tell Claude it's done. For the next ticket (Does Knock hold up against Cadence?):"
note "  workflows: discussion-question [discussions], new-enrollment [enrollments]"
note "  trigger data: actor_name, lesson_title | course_title, url"
printf '\n'
}

run_wizard "$@"; exit
